#!/usr/bin/env python3
"""Recompute scoped network results and coverage increment from frozen evidence."""
import argparse,collections,json,sys
from pathlib import Path
sys.dont_write_bytecode=True

def main():
    ap=argparse.ArgumentParser();ap.add_argument('--collection',type=Path,required=True);ap.add_argument('--baseline-coverage',type=Path,required=True);ap.add_argument('--out',type=Path,required=True);a=ap.parse_args()
    p=a.collection.resolve();source=p/'input/tool/run_network_observation.py';m={'__name__':'network_summary_frozen_runner','__file__':str(source)};exec(compile(source.read_text(),str(source),'exec'),m);result=m['audit'](p)
    counts=collections.Counter();rows=[];perkind=collections.defaultdict(list);total=0;max_thread=0;max_label=0
    for case in result['case_ids']:
        directory=p/'cases'/case;s=m['read'](directory/'summary.json');isfixture=case.startswith('fixture-');tracepath=directory/('observed.wire.n3.json' if isfixture else 'observed/n3-events.json');trace=m['read'](tracepath);events=trace['events'];threadcounts=collections.Counter(e['thread'] for e in events);total+=len(events);max_thread=max(max_thread,max(threadcounts.values()));max_label=max(max_label,max(len(e['phase'].encode()) for e in events));observed=collections.Counter(e['kind'] for e in events);counts.update(observed)
        for kind,n in observed.items():perkind[kind].append({'case':case,'count':n,'trace':str(tracepath.relative_to(p)),'summary':str((directory/'summary.json').relative_to(p))})
        row={'case':case,'kind':'fixture' if isfixture else 'network','nominal_bytes':s['nominal_bytes'],'events':len(events),'per_thread_events':dict(threadcounts),'trace_sha256':m['sha'](tracepath),'observed_kinds':dict(observed),'retained_bucket':s['retained_registry_bucket'],'mapping_count':len(s['mapping_lifetimes'])}
        if not isfixture:
            row.update(pool=s['pool'],wire_bytes=s['wire_input_bytes'],payload_bytes=s['payload_input_bytes'],owner_generations=len(s['loads']),work_exchanges=2,warm_exchanges=s['warm_exchanges'],explicit_copy_extents={k:sum(e['bytes'] for e in events if e['kind']==k) for k in ('load_header_copy','load_payload_copy','save_header_copy','save_payload_copy','string_assign_copy')},validation_domain5=s['trace_summary']['allocations']['domains']['5'])
        rows.append(row)
    baseline=m['read'](a.baseline_coverage);previous={x['kind'] for x in baseline['kinds'] if x['status']=='declared_catalog_not_executed_this_round'};new=sorted(previous&counts.keys());assert new==['auto_growth','extent_request']
    common={'diagnostic':True,'timing_evidence':False,'collection_result_sha256':m['sha'](p/'result.json'),'build_result_sha256':m['sha'](p/'build-result.json')}
    summary={'schema':'n3-network-results-v1',**common,'workload_processes':32,'reference_processes':16,'diagnostic_processes':16,'fixture_conditions':4,'network_conditions':12,'work_exchanges':24,'recorded_warm_exchanges':4,'ordinary_trace_events':total,'max_observed_events_per_thread':max_thread,'hard_events_per_thread':2048,'max_observed_phase_utf8_bytes':max_label,'valid_traces':16,'invalid_traces':0,'dropped_events':0,'all_work_and_warm_wire_bytes_equal_original_W1':True,'coverage_is_not_full_N3':True,'by_kind':dict(sorted(counts.items())),'cases':rows}
    coverage={'schema':'n3-network-coverage-increment-v1',**common,'baseline_coverage_sha256':m['sha'](a.baseline_coverage),'baseline_classification_unchanged':baseline['classification_counts'],'newly_executed_and_asserted_kinds':{k:{'count':counts[k],'scope':'separate fixture preparation, not network request','expected_per_fixture':1 if k=='auto_growth' else 2,'observations':perkind[k]} for k in new},'still_unexecuted_ordinary_kinds':sorted(previous-set(new)),'still_unexecuted_count':len(previous-set(new)),'ordinary_kind_union_count':sum(x['status'] in ('actual_structural_audit_only','actual_with_asserted_counts_or_ledger') for x in baseline['kinds'])+len(new),'current_batch_actual_kind_count':len(counts),'current_batch_observations_by_kind':dict(sorted(perkind.items())),'limits':['No catalog/runtime/contract mutation','Existing structural-only kinds are not globally reclassified from one additional workload','Known-kind tests are not native execution coverage','No new RSS sampler, performance result, or claim of complete N3 attribution']}
    a.out.mkdir(parents=True,exist_ok=False);m['write'](a.out/'summary.json',summary);m['write'](a.out/'coverage-increment.json',coverage);m['check_budget']();print(json.dumps({k:summary[k] for k in ('workload_processes','ordinary_trace_events','max_observed_events_per_thread','max_observed_phase_utf8_bytes')}))
if __name__=='__main__':main()
